#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1000000007LL;
map<long long, pair<int, long long>> val;  // gap keyed by its left boundary price (0 = start)
int gen = 0;
long long get(long long k) {
    auto it = val.find(k);
    if (it == val.end() || it->second.first != gen) return 0;
    return it->second.second;
}
void put(long long k, long long v) { val[k] = {gen, v % MOD}; }
int main() {
    int n; scanf("%d", &n);
    set<long long> S;
    long long total = 1;
    put(0, 1);
    for (int i = 0; i < n; i++) {
        char op[16]; long long p;
        scanf("%s %lld", op, &p);
        auto jt = S.lower_bound(p);
        long long a = (jt == S.begin()) ? 0 : *prev(jt);
        if (op[1] == 'D') {
            long long v = get(a);
            put(p, v);
            total = (total + v) % MOD;
            S.insert(p);
        } else {
            long long tot = (get(a) + get(p)) % MOD;
            gen++;
            put(a, tot);
            S.erase(p);
            total = tot;
        }
    }
    printf("%lld\n", total);
}

#include <bits/stdc++.h>
using namespace std;
// Rows alternate between two complementary pairs; each row is period-2 with its own start letter.
void solveRows(const vector<string>& g, int n, int m, long long& bc, vector<string>& out) {
    const char* parts[3][2] = {{"AG", "CT"}, {"AC", "GT"}, {"AT", "GC"}};
    bc = LLONG_MAX;
    for (int p = 0; p < 3; p++) for (int sw = 0; sw < 2; sw++) {
        string P[2] = {parts[p][sw], parts[p][1 - sw]};
        long long cost = 0; vector<string> res(n);
        for (int i = 0; i < n; i++) {
            const string& Q = P[i % 2];
            long long best = LLONG_MAX; string br;
            for (int st = 0; st < 2; st++) {
                string row(m, 'A'); long long c = 0;
                for (int j = 0; j < m; j++) { row[j] = Q[(j + st) % 2]; c += row[j] != g[i][j]; }
                if (c < best) { best = c; br = row; }
            }
            cost += best; res[i] = br;
        }
        if (cost < bc) { bc = cost; out = res; }
    }
}
int main() {
    int n, m; cin >> n >> m;
    vector<string> g(n);
    for (auto& s : g) cin >> s;
    long long c1, c2; vector<string> o1, o2;
    solveRows(g, n, m, c1, o1);
    vector<string> t(m, string(n, 'A'));
    for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) t[j][i] = g[i][j];
    solveRows(t, m, n, c2, o2);
    if (c1 <= c2) { for (auto& r : o1) cout << r << "\n"; }
    else {
        vector<string> r(n, string(m, 'A'));
        for (int j = 0; j < m; j++) for (int i = 0; i < n; i++) r[i][j] = o2[j][i];
        for (auto& x : r) cout << x << "\n";
    }
}

