int par[200005];
int findp(int x) { return par[x] == x ? x : par[x] = findp(par[x]); }
int main() {
    int n, m; scanf("%d %d", &n, &m);
    vector<tuple<int, int, int>> e(m);
    for (auto& [w, u, v] : e) { scanf("%d %d %d", &u, &v, &w); }
    for (int i = 1; i <= n; i++) par[i] = i;
    sort(e.begin(), e.end());
    long long ans = 0;
    for (int i = 0; i < m;) {
        int j = i;
        while (j < m && get<0>(e[j]) == get<0>(e[i])) j++;
        int c = 0, k = 0;
        for (int t = i; t < j; t++) { auto [w, u, v] = e[t]; if (findp(u) != findp(v)) c++; }
        for (int t = i; t < j; t++) {
            auto [w, u, v] = e[t];
            int a = findp(u), b = findp(v);
            if (a != b) { par[a] = b; k++; }
        }
        ans += c - k;
        i = j;
    }
    printf("%lld\n", ans);
}

