// Stack of prefix-maximum chain; list of values kept in order; node i inserted just below next_i.
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; scanf("%d", &n);
        vector<int> nx(n + 2), pr(n + 2), nt(n + 2);
        vector<char> in(n + 2, 0);
        for (int i = 1; i <= n; i++) scanf("%d", &nx[i]);
        nt[0] = n + 1; pr[n + 1] = 0;
        auto insertBefore = [&](int x, int j) {
            int p = pr[j]; nt[p] = x; pr[x] = p; nt[x] = j; pr[j] = x;
        };
        vector<int> st = {n + 1};
        in[n + 1] = 1;
        bool ok = true;
        for (int i = n; i >= 1 && ok; i--) {
            int j = (nx[i] == -1) ? i + 1 : nx[i];
            if (!in[j]) { ok = false; break; }
            while (st.back() != j) { in[st.back()] = 0; st.pop_back(); }
            st.push_back(i); in[i] = 1;
            insertBefore(i, j);
        }
        if (!ok) { puts("-1"); continue; }
        vector<int> p(n + 1);
        int x = nt[0], v = 1;
        while (x != n + 1) { p[x] = v++; x = nt[x]; }
        for (int i = 1; i <= n; i++) printf("%d ", p[i]);
        puts("");
    }
}

