int main() {
    int n; ll r; cin >> n >> r;
    vector<pair<ll, ll>> pos, neg;
    for (int i = 0; i < n; i++) {
        ll a, b; cin >> a >> b;
        if (b >= 0) pos.push_back({a, b}); else neg.push_back({a, b});
    }
    sort(pos.begin(), pos.end());  // gains first, by requirement
    sort(neg.begin(), neg.end(), [](const pair<ll, ll>& x, const pair<ll, ll>& y) {
        return x.first + x.second > y.first + y.second;
    });
    bool ok = true;
    auto go = [&](pair<ll, ll> pr) {
        if (r < pr.first || r + pr.second < 0) return false;
        r += pr.second; return true;
    };
    for (auto pr : pos) if (!go(pr)) { ok = false; break; }
    if (ok) for (auto pr : neg) if (!go(pr)) { ok = false; break; }
    puts(ok ? "YES" : "NO");
}

