// Row r flips cells (r,j) ^= b[j]; column c flips (i,c) ^= b[i]. Pick pivot k with b[k]=1, guess x[k],y[k].
int main() {
    int N; cin >> N;
    vector<string> a(N), t(N);
    for (auto& s : a) cin >> s;
    for (auto& s : t) cin >> s;
    string b; cin >> b;
    auto B = [&](int i) { return b[i] - '0'; };
    auto D = [&](int i, int j) { return (a[i][j] - '0') ^ (t[i][j] - '0'); };
    int k = -1;
    for (int i = 0; i < N; i++) if (B(i)) { k = i; break; }
    if (k < 0) {
        bool ok = true;
        for (int i = 0; i < N; i++) for (int j = 0; j < N; j++) if (D(i, j)) ok = false;
        puts(ok ? "0" : "-1");
        return 0;
    }
    for (int xk = 0; xk < 2; xk++) for (int yk = 0; yk < 2; yk++) {
        vector<int> X(N), Y(N);
        X[k] = xk; Y[k] = yk;
        for (int i = 0; i < N; i++) if (i != k) X[i] = D(i, k) ^ (yk & B(i));
        for (int j = 0; j < N; j++) if (j != k) Y[j] = D(k, j) ^ (xk & B(j));
        bool ok = true;
        for (int i = 0; i < N && ok; i++) for (int j = 0; j < N && ok; j++)
            if (((X[i] & B(j)) ^ (Y[j] & B(i))) != D(i, j)) ok = false;
        if (!ok) continue;
        vector<string> ops;
        for (int i = 0; i < N; i++) if (X[i]) ops.push_back("row " + to_string(i));
        for (int j = 0; j < N; j++) if (Y[j]) ops.push_back("col " + to_string(j));
        printf("%d\n", (int)ops.size());
        for (auto& o : ops) printf("%s\n", o.c_str());
        return 0;
    }
    puts("-1");
}

