int main() {
    int n; scanf("%d", &n);
    vector<ll> a(n);
    ll S = 0;
    for (auto& x : a) { scanf("%lld", &x); S += x; }
    if (S == 1) { puts("-1"); return 0; }
    vector<ll> primes; ll T = S;
    for (ll d = 2; d * d <= T; d++) if (T % d == 0) { primes.push_back(d); while (T % d == 0) T /= d; }
    if (T > 1) primes.push_back(T);
    ll best = LLONG_MAX;
    for (ll p : primes) {
        ll pref = 0, cost = 0;
        for (int i = 0; i < n - 1; i++) { pref += a[i]; ll r = pref % p; cost += min(r, p - r); }
