using namespace std;
typedef long long ll;
// Each milestone (s,t) with t < a_s always fires, giving one free unit of u.
// Turns = sum_i max(0, a_i - F_i), F_i = active milestones rewarding i.
int main() {
    int n; scanf("%d", &n);
    vector<ll> a(n + 1), F(n + 1, 0);
    ll total = 0;
    for (int i = 1; i <= n; i++) { scanf("%lld", &a[i]); total += a[i]; }
    auto contrib = [&](int i) { return max(0LL, a[i] - F[i]); };
    map<pair<int, ll>, int> ms;
    int q; scanf("%d", &q);
    while (q--) {
        int s, u; ll t; scanf("%d %lld %d", &s, &t, &u);
        auto key = make_pair(s, t);
        auto it = ms.find(key);
        if (it != ms.end()) {
            int u0 = it->second;
            if (t < a[s]) { total -= contrib(u0); F[u0]--; total += contrib(u0); }
            ms.erase(it);
        }
        if (u != 0) {
            ms[key] = u;
            if (t < a[s]) { total -= contrib(u); F[u]++; total += contrib(u); }
        }
        printf("%lld\n", total);
    }
}

