int main() {
    int n; scanf("%d", &n);
    vector<vector<pair<int, int>>> adj(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int x, y; scanf("%d %d", &x, &y);
        adj[x].push_back({y, i}); adj[y].push_back({x, i});
    }
    vector<int> par(n + 1, 0), pe(n + 1, -1), dep(n + 1, -1);
    queue<int> Q; Q.push(1); dep[1] = 0;
    while (!Q.empty()) {
        int u = Q.front(); Q.pop();
        for (auto [v, e] : adj[u]) if (dep[v] < 0) { dep[v] = dep[u] + 1; par[v] = u; pe[v] = e; Q.push(v); }
    }
    int m; scanf("%d", &m);
    vector<array<int, 3>> cs(m);
    for (auto& c : cs) scanf("%d %d %d", &c[0], &c[1], &c[2]);
    vector<int> L(n - 1, 1);
    auto path = [&](int a, int b) {
        vector<int> es;
        while (a != b) { if (dep[a] < dep[b]) swap(a, b); es.push_back(pe[a]); a = par[a]; }
        return es;
    };
    for (auto& c : cs) for (int e : path(c[0], c[1])) L[e] = max(L[e], c[2]);
    for (auto& c : cs) {
        int mn = INT_MAX;
        for (int e : path(c[0], c[1])) mn = min(mn, L[e]);
        if (mn != c[2]) { puts("-1"); return 0; }
    }
    for (int i = 0; i < n - 1; i++) printf("%d%c", L[i], i + 1 < n - 1 ? ' ' : '\n');
}

