#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// Target H: candidates are every h_i and floor/ceil of the average (cost is piecewise linear in H).
int main() {
    ll N, A, R, M; cin >> N >> A >> R >> M;
    vector<ll> h(N);
    for (auto& x : h) cin >> x;
    sort(h.begin(), h.end());
    vector<ll> pre(N + 1, 0);
    for (ll i = 0; i < N; i++) pre[i + 1] = pre[i] + h[i];
    ll S = pre[N];
    ll up = min(M, A + R);
    auto cost = [&](ll H) {
        ll i = lower_bound(h.begin(), h.end(), H) - h.begin();   // count h < H
        ll j = upper_bound(h.begin(), h.end(), H) - h.begin();   // count h <= H
        ll Q = H * i - pre[i];                 // bricks to add
        ll P = (S - pre[j]) - H * (N - j);     // bricks to remove
        ll res = min(P, Q) * up;
        res += (P > Q) ? (P - Q) * R : (Q - P) * A;
        return res;
    };
    vector<ll> cand = h;
    cand.push_back(S / N);
    cand.push_back((S + N - 1) / N);
    ll best = LLONG_MAX;
    for (ll H : cand) best = min(best, cost(H));
    cout << best << "\n";
}

