int main() {
    int n, m, K; scanf("%d %d %d", &n, &m, &K);
    vector<vector<int>> g(n + 1);
    for (int i = 0; i < m; i++) { int u, v; scanf("%d %d", &u, &v); g[u].push_back(v); g[v].push_back(u); }
    vector<int> order, vis(n + 1, 0), par(n + 1, 0), dep(n + 1, -1);
    vector<char> inS(n + 1, 0);
    queue<int> q; q.push(1); vis[1] = 1;   // first K BFS vertices form a connected set S
    while (!q.empty() && (int)order.size() < K) {
        int u = q.front(); q.pop(); order.push_back(u); inS[u] = 1;
        for (int v : g[u]) if (!vis[v]) { vis[v] = 1; q.push(v); }
    }
    queue<int> t; t.push(1); dep[1] = 0;   // BFS tree inside S
    while (!t.empty()) {
        int u = t.front(); t.pop();
        for (int v : g[u]) if (inS[v] && dep[v] < 0) { dep[v] = dep[u] + 1; par[v] = u; t.push(v); }
    }
    int a = -1, b = -1;  // a non-tree edge inside S
    for (int u : order) for (int v : g[u]) if (inS[v] && v != par[u] && u != par[v]) a = u, b = v;
    if (a < 0) {             // S is a tree: take the larger colour class
        vector<int> c[2];
        for (int u : order) c[dep[u] % 2].push_back(u);
        auto& big = c[0].size() >= c[1].size() ? c[0] : c[1];
        printf("1\n");
        for (int i = 0; i < (K + 1) / 2; i++) printf("%d ", big[i]);
        return puts(""), 0;
    }
    vector<int> ca, cb;      // cycle = a..lca..b, closed by edge b-a
    int x = a, y = b;
    while (x != y) {
        if (dep[x] >= dep[y]) { ca.push_back(x); x = par[x]; }
        else { cb.push_back(y); y = par[y]; }
    }
    ca.push_back(x);
    for (int i = (int)cb.size() - 1; i >= 0; i--) ca.push_back(cb[i]);
    printf("2\n%d\n", (int)ca.size());
    for (int v : ca) printf("%d ", v);
    printf("\n");
}

