#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// Optimal fill of '?' is a threshold: a prefix of '?' gets one value, the rest the other.
// Sweep flips left to right and update the cost in O(1) per flip using prefix counts.
int main() {
    char buf[100005]; scanf("%s", buf);
    string s = buf; int n = s.size();
    ll x, y; scanf("%lld %lld", &x, &y);
    vector<ll> f0(n + 1, 0), f1(n + 1, 0), q(n + 1, 0);
    for (int i = 0; i < n; i++) {
        f0[i + 1] = f0[i] + (s[i] == '0'); f1[i + 1] = f1[i] + (s[i] == '1'); q[i + 1] = q[i] + (s[i] == '?');
    }
    ll best = LLONG_MAX;
    for (int v = 0; v < 2; v++) {          // '?' start as v, flip to fv
        int fv = 1 - v;
        ll C = 0, z = 0, o = 0;            // cost of the start string
        for (int i = 0; i < n; i++) {
            int c = (s[i] == '?') ? v : s[i] - '0';
            if (c == 1) { C += x * z; o++; } else { C += y * o; z++; }
        }
        best = min(best, C);
        for (int p = 0; p < n; p++) {
            if (s[p] != '?') continue;
            ll zb = f0[p] + (fv == 0 ? q[p] : 0), ob = f1[p] + (fv == 1 ? q[p] : 0);
            ll za = (f0[n] - f0[p + 1]) + (v == 0 ? q[n] - q[p + 1] : 0);
            ll oa = (f1[n] - f1[p + 1]) + (v == 1 ? q[n] - q[p + 1] : 0);
            auto contrib = [&](int w) { return w == 1 ? x * zb + y * za : y * ob + x * oa; };
            C += contrib(fv) - contrib(v);
            best = min(best, C);
        }
    }
    printf("%lld\n", best);
}

