    while (t--) {
        int n; scanf("%d", &n);
        vector<int> a(n + 2), pm(n + 2), sm(n + 2);
        for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
        pm[0] = INT_MIN; for (int i = 1; i <= n; i++) pm[i] = max(pm[i - 1], a[i]);
        sm[n + 1] = INT_MIN; for (int i = n; i >= 1; i--) sm[i] = max(sm[i + 1], a[i]);
        int LG = 1; while ((1 << LG) <= n) LG++;
        vector<vector<int>> sp(LG, vector<int>(n + 2));
        sp[0] = a;
        for (int k = 1; k < LG; k++) for (int i = 1; i + (1 << k) - 1 <= n; i++) sp[k][i] = min(sp[k - 1][i], sp[k - 1][i + (1 << (k - 1))]);
        auto rmq = [&](int l, int r) { int k = 31 - __builtin_clz(r - l + 1); return min(sp[k][l], sp[k][r - (1 << k) + 1]); };
        map<int, vector<int>> pos;
        for (int i = 1; i <= n; i++) pos[a[i]].push_back(i);
        bool found = false;
        for (int l = 2; l <= n - 1 && !found; l++) {
            int v = pm[l - 1];
            int lo = l, hi = n + 1;   // first j >= l with a[j] < v (n+1 if none)
            while (lo < hi) { int mid = (lo + hi) / 2; if (rmq(l, mid) < v) hi = mid; else lo = mid + 1; }
            int R = min(lo - 1, n - 1);
            auto it = pos.find(v);
            if (it == pos.end()) continue;
            auto pit = lower_bound(it->second.begin(), it->second.end(), l);
            if (pit == it->second.end() || *pit > R) continue;
            int f = *pit;
            int L2 = f + 1, H2 = R + 1, x = f + 1, y = n + 1;  // t = r+1
            while (x < y) { int mid = (x + y) / 2; if (sm[mid] <= v) y = mid; else x = mid + 1; }
            if (x <= H2 && x >= L2 && sm[x] == v) {
                int r = x - 1;
                printf("YES\n%d %d %d\n", l - 1, r - l + 1, n - r);
                found = true;
            }
        }
        if (!found) puts("NO");
    }
}

#include <bits/stdc++.h>
using namespace std;
// Vectors are edges between coordinates (node 0 = "no coordinate"); a greedy DSU pass in index order
// gives the rank r, so |T| = 2^r, and the chosen indices form the lexicographically smallest basis.
vector<int> par;
int findp(int x) {
    int r = x; while (par[r] != r) r = par[r];
    while (par[x] != r) { int nx = par[x]; par[x] = r; x = nx; }
    return r;
}
int main() {
    const long long MOD = 1000000007LL;
    int n, m; scanf("%d %d", &n, &m);
    par.resize(m + 1);
    for (int i = 0; i <= m; i++) par[i] = i;
    vector<int> chosen;
    for (int i = 1; i <= n; i++) {
        int k; scanf("%d", &k);
        int u = 0, v = 0;
        if (k == 1) scanf("%d", &u); else scanf("%d %d", &u, &v);
        int a = findp(u), b = findp(v);
        if (a != b) { par[a] = b; chosen.push_back(i); }
    }
    long long p = 1;
    for (size_t i = 0; i < chosen.size(); i++) p = p * 2 % MOD;
    printf("%lld %d\n", p, (int)chosen.size());
    for (size_t i = 0; i < chosen.size(); i++) printf("%d%c", chosen[i], i + 1 < chosen.size() ? ' ' : '\n');
    if (chosen.empty()) puts("");
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// Gift sets: with a >= b, k sets are feasible iff some p (type-1 count) satisfies both colour limits.
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        ll x, y, a, b; scanf("%lld %lld %lld %lld", &x, &y, &a, &b);
        if (a < b) swap(a, b);
        auto ok = [&](ll k) {
            if (k * b > x || k * b > y) return false;
            if (a == b) return true;
            ll L = max(0LL, k - (y - k * b) / (a - b));
            ll R = min(k, (x - k * b) / (a - b));
            return L <= R;
        };
        ll lo = 0, hi = (x + y) / (a + b);
        while (lo < hi) { ll mid = (lo + hi + 1) / 2; if (ok(mid)) lo = mid; else hi = mid - 1; }
        printf("%lld\n", lo);
    }
}

#include <bits/stdc++.h>
using namespace std;
// Labels with equal top bit are never adjacent, so for every edge u^v > min(u,v) and nobody can move.
// Groups G_k = [2^k, 2^{k+1}); give the smaller colour class a set of whole groups of total size |class|.
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; scanf("%d", &n);
        vector<vector<int>> g(n + 1);
        for (int i = 0; i < n - 1; i++) { int u, v; scanf("%d %d", &u, &v); g[u].push_back(v); g[v].push_back(u); }
        vector<int> col(n + 1, -1); col[1] = 0;
        queue<int> q; q.push(1);
        int c0 = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (col[u] == 0) c0++;
            for (int v : g[u]) if (col[v] < 0) { col[v] = col[u] ^ 1; q.push(v); }
        }
        vector<pair<int, int>> rg;
        for (int lo = 1; lo <= n; lo <<= 1) rg.push_back({lo, min(2 * lo - 1, n)});
        int G = rg.size();
        vector<vector<char>> dp(G + 1, vector<char>(c0 + 1, 0));
        dp[0][0] = 1;
        for (int i = 0; i < G; i++) {
            int sz = rg[i].second - rg[i].first + 1;
            for (int s = 0; s <= c0; s++) dp[i + 1][s] = dp[i][s] || (s >= sz && dp[i][s - sz]);
        }
        vector<char> useG(G, 0);
        int s = c0;
        for (int i = G; i > 0; i--) {
            int sz = rg[i - 1].second - rg[i - 1].first + 1;
            if (!dp[i - 1][s]) { useG[i - 1] = 1; s -= sz; }
        }
        vector<int> A, B;
        for (int i = 0; i < G; i++) for (int v = rg[i].first; v <= rg[i].second; v++) (useG[i] ? A : B).push_back(v);
        int ia = 0, ib = 0;
        for (int u = 1; u <= n; u++) printf("%d%c", col[u] == 0 ? A[ia++] : B[ib++], u < n ? ' ' : '\n');
    }
}

#include <bits/stdc++.h>
using namespace std;
// Groups must hold a power of two (empty group costs 1). Cut p = #values < x, q = #values < y.
// For each light cut p and heavy bucket 2^k, take the smallest feasible middle cut q.
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; scanf("%d", &n);
        vector<int> s(n); for (auto& x : s) scanf("%d", &x);
        sort(s.begin(), s.end());
        auto valid = [&](int p) { return p == 0 || p == n || s[p - 1] < s[p]; };
        auto gap2 = [&](int p) { return p == 0 || p == n || (long long)s[p] - s[p - 1] >= 2; };
        vector<int> nv(n + 2, INT_MAX);
        for (int p = n; p >= 0; p--) nv[p] = valid(p) ? p : nv[p + 1];
        auto P = [&](long long c) { long long r = 1; while (r < c) r <<= 1; return r; };
        long long best = LLONG_MAX;
        for (int p = 0; p <= n; p++) {
            if (!valid(p)) continue;
            for (int k = 0; k <= 18; k++) {
                long long lo = max<long long>(p, (long long)n - (1LL << k));
                int q = nv[lo];
                if (q == p && !gap2(p)) q = nv[p + 1];
                if (q == INT_MAX || q > n) continue;
                best = min(best, P(p) + P(q - p) + P(n - q) - n);
            }
        }
        printf("%lld\n", best);
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// For target MEX m: cnt[m] elements must change, miss(m) missing values in [0,m) must be filled,
// and the cost is the number of distinct values > m that survive. Greedily wipe the rarest big values.
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; ll k; scanf("%d %lld", &n, &k);
        vector<int> cnt(n + 2, 0);
        map<ll, int> big;
        for (int i = 0; i < n; i++) { ll x; scanf("%lld", &x); if (x <= n) cnt[x]++; else big[x]++; }
        int LOG = 1; while ((1 << LOG) <= n) LOG++;
        vector<ll> numT(n + 1, 0), sumT(n + 1, 0), numAt(n + 2, 0);
        auto upd = [&](int c, int d) {
            numAt[c] += d;
            for (int i = c; i <= n; i += i & -i) { numT[i] += d; sumT[i] += (ll)d * c; }
        };
        ll bigCount = 0;
        for (int v = 0; v <= n; v++) if (cnt[v] > 0) { upd(cnt[v], 1); bigCount++; }
        for (auto& [v, c] : big) { upd(c, 1); bigCount++; }
        ll best = LLONG_MAX, distinctLess = 0;
        for (int m = 0; m <= n; m++) {
            if (cnt[m] > 0) { upd(cnt[m], -1); bigCount--; }   // big = values > m
            ll miss = m - distinctLess;
            if (cnt[m] <= k && miss <= k) {
                ll budget = k - cnt[m];
                ll S = 0, C = 0; int pos = 0;
                for (int st = 1 << LOG; st > 0; st >>= 1)
                    if (pos + st <= n && S + sumT[pos + st] <= budget) { pos += st; S += sumT[pos]; C += numT[pos]; }
                ll removable = C;
                if (pos + 1 <= n) removable += min((budget - S) / (pos + 1), numAt[pos + 1]);
                best = min(best, bigCount - removable);
            }
            if (cnt[m] > 0) distinctLess++;
        }
        printf("%lld\n", best);
    }
}
